-- K11 control for dissolution timing: 1989-98 formations, ever filed an annual return / accounts, split by dissolution period, the 23 addresses vs everywhere else
WITH m AS (SELECT COMPANY_ID id, INCORPORATION_DATE d, YEAR(INCORPORATION_DATE) y, REGEXP_REPLACE(UPPER(SPLIT_PART(REGISTERED_ADDRESS, ',', 1) || SPLIT_PART(REGISTERED_ADDRESS, ',', 2)), '[^A-Z0-9]', '') a2 FROM LIBRARY_MARTS.CORPORATE_REGISTRY.CORPORATE_REGISTRY__INTL_IE_CRO WHERE INCORPORATION_DATE IS NOT NULL AND INCORPORATION_DATE <> '1901-01-01' AND REGISTERED_ADDRESS NOT ILIKE '%NO ADDRESS%'),
r AS (SELECT TRIM(COMPANY_NUM) rid, TRY_TO_DATE(TRIM(LAST_AR_DATE),'YYYY-MM-DD') ar, TRY_TO_DATE(TRIM(LAST_ACCOUNTS_DATE),'YYYY-MM-DD') acc, TRY_TO_DATE(TRIM(COMP_DISSOLVED_DATE),'YYYY-MM-DD') dd FROM LIBRARY_RAW.LANDING.INTL_IE_CRO QUALIFY ROW_NUMBER() OVER (PARTITION BY TRIM(COMPANY_NUM) ORDER BY _INGESTED_AT DESC) = 1)
SELECT IFF(m.a2 IN ('41CENTRALCHAMBERSDAMECOURT', '20CLANWILLIAMTERRACEDUBLIN2', 'FOURTHFLOORDOLLARDHOUSE', '6LOWERHATCHSTREETDUBLIN2', 'FIRSTFLOOR1415PARLIAMENTSTREET', 'FIRSTFLOOR17DAMESTREET', 'MERCHANTSHOUSE2730MERCHANTSQUAY', '1STOKESPLACESTSTEPHENSGREEN', '98LOWERBAGGOTSTREETDUBLIN2', '2CLANWILLIAMTERRACEDUBLIN2', '57DAMESTREETDUBLIN2', '17DAMESTREETDUBLIN2', '109LOWERBAGGOTSTREETDUBLIN2', '56FITZWILLIAMSQUAREDUBLIN2', '2729LOWERPEMBROKESTREETDUBLIN2', '48FITZWILLIAMSQUAREDUBLIN2', 'SUITE441LOWERBAGGOTSTREET', '4LOWERHATCHSTREETDUBLIN2', 'STRATTONHOUSEBISHOPSTOWNROAD', '11ANGLESEASTREETDUBLIN2', '17EARLSFORTTERRACEDUBLIN2', '2NDFLOOR3CHRISTCHURCHSQUARE', '8INNSCOURTWINETAVERNSTREET'), 'a_mass23', 'c_rest') cls,
       CASE WHEN r.dd IS NULL THEN 'not dissolved' WHEN YEAR(r.dd) <= 1998 THEN 'diss_1993_98' WHEN YEAR(r.dd) <= 2000 THEN 'diss_1999_00' ELSE 'diss_2001_plus' END dp,
       COUNT(*) n, COUNT_IF(r.ar IS NOT NULL) ever_ar, COUNT_IF(r.acc IS NOT NULL) ever_acc
FROM m LEFT JOIN r ON r.rid = m.id WHERE m.y BETWEEN 1989 AND 1998 GROUP BY 1,2 ORDER BY 1,2
